import 'dart:io';
import 'dart:typed_data';

// Inputs are pinned in Git so generation and CI never depend on the network.
void main(List<String> arguments) {
  const source = 'tool/unicode/16.0.0';
  final output = File(
    'packages/xterm/lib/src/utils/unicode_16_width_data.dart',
  );
  final result = StringBuffer()
    ..writeln(
      '// Generated by tool/generate_unicode_width_data.dart. Do not edit.',
    )
    ..writeln(
      '// Source: Unicode 16.0.0 EastAsianWidth.txt and emoji/emoji-data.txt.',
    )
    ..writeln('// See tool/unicode/README.md for provenance and regeneration.')
    ..writeln();
  for (final entry in [
    ('unicode16Wide', 'EastAsianWidth.txt', {'W', 'F'}),
    ('unicode16Ambiguous', 'EastAsianWidth.txt', {'A'}),
    ('unicode16EmojiPresentation', 'emoji-data.txt', {'Emoji_Presentation'}),
    (
      'unicode16ExtendedPictographic',
      'emoji-data.txt',
      {'Extended_Pictographic'},
    ),
  ]) {
    final included = Uint8List(0x110000);
    var matches = 0;
    for (final line in File('$source/${entry.$2}').readAsLinesSync()) {
      final fields = line.split('#').first.split(';');
      if (fields.length != 2 || !entry.$3.contains(fields[1].trim())) continue;
      final bounds = fields[0].trim().split('..');
      final first = int.parse(bounds.first, radix: 16);
      final last = int.parse(bounds.last, radix: 16);
      included.fillRange(first, last + 1, 1);
      matches++;
    }
    if (matches == 0) throw StateError('No ${entry.$3} in ${entry.$2}');
    result.writeln('const ${entry.$1} = <List<int>>[');
    int? start;
    for (var scalar = 0; scalar <= included.length; scalar++) {
      final present = scalar < included.length && included[scalar] != 0;
      if (present && start == null) start = scalar;
      if (!present && start != null) {
        result.writeln(
          '  [0x${start.toRadixString(16)}, 0x${(scalar - 1).toRadixString(16)}],',
        );
        start = null;
      }
    }
    result.writeln('];');
    result.writeln();
  }
  final generated = '${result.toString().trimRight()}\n';
  if (arguments.contains('--check')) {
    if (!output.existsSync() || output.readAsStringSync() != generated) {
      stderr.writeln(
        'Unicode width data is stale. Run dart tool/generate_unicode_width_data.dart',
      );
      exitCode = 1;
    }
  } else {
    output.writeAsStringSync(generated);
  }
}
